export const HTML = "<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700;1,900&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<header class=\"topo\">\n  <nav class=\"barra\" aria-label=\"Topo\">\n    <a class=\"marca-news\" href=\"#inicio\">\n      <img src=\"/ebook-web/simbolo.png\" alt=\"\" width=\"28\" height=\"28\" loading=\"eager\" decoding=\"async\">\n      <span class=\"palavra\"><em>Notas</em> do Café</span>\n    </a>\n    <a class=\"botao botao-curto\" href=\"/ebook-premium/checkout\">Quero o guia</a>\n  </nav>\n</header>\n\n<main>\n<section class=\"heroi\" id=\"inicio\">\n  <img class=\"capa-heroi\" src=\"/ebook-web/capa-notas-do-cafe.webp\" alt=\"Capa do guia Café de Balcão no Coador de Casa\" width=\"1800\" height=\"2400\" loading=\"eager\" decoding=\"async\" fetchpriority=\"high\">\n  <p class=\"olho\">Café de Balcão no Coador de Casa · o guia</p>\n  <h1>Amanhã cedo, você acha em 3 minutos a variável que amarga o seu café, antes de sair pro balcão.</h1>\n  <p class=\"sub\">Pra quem ainda paga o balcão. Cada variável fecha em <b>sim ou não</b>. Abaixo, seis frases antes e depois, e a variável 1 pra fazer com o pacote na mão.</p>\n  <div class=\"acao\">\n    <a class=\"botao\" href=\"/ebook-premium/checkout\">Quero o guia →</a>\n    <p class=\"preco\"><strong>R$&nbsp;27</strong> · uma vez só · pix ou cartão</p>\n    <p class=\"reforco\">Do time da news Notas do Café, 2,4 mil leitores todo dia às 8h08.</p>\n  </div>\n</section>\n\n<section class=\"bloco centro\" id=\"prova\">\n  <div class=\"miolo\">\n    <h2 class=\"revela\">Seis frases de café, antes e depois.</h2>\n    <p class=\"intro revela\" style=\"--i:1\">Quem coa não vê onde o amargo nasce: o gole acusa o pó, e a colher, a chaleira e o jato passam sem suspeita. Cada frase abaixo reprovou numa das 8 variáveis e voltou aprovada. Escolha a aba e vire o cartão.</p>\n    <div class=\"pares\" role=\"tablist\" aria-label=\"Seis frases, antes e depois\">\n<button class=\"par\" type=\"button\" role=\"tab\" aria-selected=\"true\" data-i=\"0\">Lista</button>\n    <button class=\"par\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-i=\"1\">Torrefação</button>\n    <button class=\"par\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-i=\"2\">Receita</button>\n    <button class=\"par\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-i=\"3\">Chaleira</button>\n    <button class=\"par\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-i=\"4\">Despejo</button>\n    <button class=\"par\" type=\"button\" role=\"tab\" aria-selected=\"false\" data-i=\"5\">Caderno</button>\n    \n    <span class=\"risco\" aria-hidden=\"true\"></span>\n  </div>\n\n  <div class=\"palco\">\n    <div class=\"cartao longe\" id=\"cartao\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"Cartão com lista do mercado. Toque pra virar entre antes e depois.\">\n      <div class=\"giro\">\n        <article class=\"face face-antes\" id=\"faceAntes\">\n          <div class=\"face-topo\">\n            <span id=\"ctxAntes\">lista do mercado</span>\n            <span class=\"estado\"><svg viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M2.4 2.4l7.2 7.2M9.6 2.4l-7.2 7.2\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" fill=\"none\"/></svg><span class=\"estado-texto\">variável 1 · falhou</span></span>\n          </div>\n          <p class=\"trecho\" id=\"trechoAntes\"></p>\n          <p class=\"assinado\"><b>Reprovou na</b><span id=\"ondeFalhou\"></span></p>\n        </article>\n        <article class=\"face face-depois\" id=\"faceDepois\">\n          <div class=\"face-topo\">\n            <span id=\"ctxDepois\">lista do mercado</span>\n            <span class=\"estado\"><svg viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M2.2 6.4l2.6 2.6L9.8 3.2\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\"/></svg><span class=\"estado-texto\">variável 1 · passou</span></span>\n          </div>\n          <p class=\"trecho\" id=\"trechoDepois\"></p>\n          <p class=\"assinado\"><b>O que entrou</b><span id=\"oQueEntrou\"></span></p>\n        </article>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"mesa\">\n    <p class=\"criterio\" id=\"criterio\"><span class=\"criterio-rotulo\" id=\"criterioRotulo\">Critério</span><span id=\"criterioTexto\"></span></p>\n  </div>\n\n  <div class=\"interruptor\" id=\"interruptor\" role=\"group\" aria-label=\"Antes ou depois\">\n    <span class=\"polegar\" aria-hidden=\"true\"></span>\n    <button class=\"lado\" type=\"button\" data-lado=\"antes\" aria-pressed=\"true\">Antes</button>\n    <button class=\"lado\" type=\"button\" data-lado=\"depois\" aria-pressed=\"false\">Depois</button>\n  </div>\n  </div>\n</section>\n\n<section class=\"bloco\" id=\"agora\">\n  <div class=\"miolo agora\">\n    <h2 class=\"revela\">Vire o pacote de café e leia o rótulo de trás pra frente.</h2>\n    <p class=\"intro revela\" style=\"--i:1\">Um minuto, na cozinha ou na gôndola, com o pacote que você já tem.</p>\n    <div class=\"folha revela\" style=\"--i:2\">\n      <h3>O movimento</h3>\n      <ol class=\"passos\"><li data-n=\"01\">Procure a data de torra, não a validade. Validade fala de segurança do alimento; data de torra fala de aroma. Pacote sem ela já reprovou.</li><li data-n=\"02\">Confira o grau de torra e mire na torra média: já perdeu a acidez verde, ainda não ganhou gosto de queima. Extraforte amarga antes de a água chegar.</li><li data-n=\"03\">Veja se é grão inteiro ou moído. O moído perde aroma poucos dias depois de aberto, e despejo nenhum devolve o que evaporou.</li><li data-n=\"04\">Faça a conta do consumo: a 15 gramas por xícara, 250 gramas rendem perto de 16. O pacote tem que acabar dentro de um mês.</li></ol>\n      <h3>Os critérios que esta variável cobra</h3>\n      <ul class=\"criterios\"><li data-n=\"01\">O pacote traz a data de torra impressa, e o grão saiu do torrador há menos de dois meses.</li><li data-n=\"02\">O grão é inteiro, de torra média, em pacote que acaba dentro de um mês.</li></ul>\n      <p class=\"fim\">Reprovou em um dos dois? O guia mostra o movimento que conserta a próxima ida ao mercado e as outras 7 variáveis que a sua coada ainda vai passar.</p>\n    </div>\n    <div class=\"acao revela\" style=\"--i:3\">\n      <a class=\"botao\" href=\"/ebook-premium/checkout\">Quero o guia →</a>\n      <p class=\"reforco\">Melhorou a coada ou devolve · 7 dias</p>\n    </div>\n  </div>\n</section>\n\n<section class=\"bloco\" id=\"testes\">\n  <div class=\"miolo\">\n    <h2 class=\"revela\">As oito variáveis, uma por capítulo.</h2>\n    <p class=\"intro revela\" style=\"--i:1\">A variável que você acabou de conferir é o capítulo 01. Cada uma cobra um ou dois critérios na sua coada; quatro estão aqui, os outros ficam no guia.</p>\n    <ol class=\"sanfona\">\n      <li class=\"dobra revela\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"true\" aria-controls=\"t1\"><span class=\"num\">01</span><span class=\"titulo\">O grão e a torra do rótulo</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo aberto\" id=\"t1\"><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Vira o pacote e lê os dois campos que decidem a xícara, data de torra e grau de torra, em grão inteiro.</p>\n          <ul class=\"criterios\"><li data-n=\"01\">O pacote traz a data de torra impressa, e o grão saiu do torrador há menos de dois meses.</li><li data-n=\"02\">O grão é inteiro, de torra média, em pacote que acaba dentro de um mês.</li></ul>\n        </div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:1\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"t2\"><span class=\"num\">02</span><span class=\"titulo\">A moagem de areia grossa</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"t2\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Mói na hora, na textura de areia grossa, e ajusta um clique pelo tempo de escoamento.</p>\n          <ul class=\"criterios\"><li data-n=\"03\">O pó tem textura de areia grossa entre os dedos, com grão separado, nunca talco.</li><li data-n=\"04\">A coada escoa entre 2min30 e 3min30, da primeira gota à última.</li></ul>\n        </div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:2\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"t3\"><span class=\"num\">03</span><span class=\"titulo\">A dose que sai da balança</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"t3\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Pesa 15 gramas de café pra cada 240 mililitros de água e repete a dose todo dia.</p>\n          <p class=\"no-ebook\">Os critérios ficam no guia.</p>\n        </div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:3\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"t4\"><span class=\"num\">04</span><span class=\"titulo\">A água fora da fervura</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"t4\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Desliga o fogo na fervura e conta de 30 a 60 segundos, tampa aberta, antes de molhar o pó.</p>\n          <ul class=\"criterios\"><li data-n=\"05\">A água espera de 30 a 60 segundos fora da fervura, com a tampa aberta, antes de encostar no pó.</li><li data-n=\"06\">Se a água da torneira tem gosto próprio no copo, a coada usa água filtrada.</li></ul>\n        </div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:4\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"t5\"><span class=\"num\">05</span><span class=\"titulo\">O pré-molho que solta o gás</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"t5\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Molha todo o pó com o dobro do peso dele em água e espera o gás baixar antes do despejo principal.</p>\n          <p class=\"no-ebook\">Os critérios ficam no guia.</p>\n        </div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:5\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"t6\"><span class=\"num\">06</span><span class=\"titulo\">O fio fino em espiral</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"t6\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Despeja em fio fino, do centro pra borda, em duas levas, com o bule perto do pó.</p>\n          <ul class=\"criterios\"><li data-n=\"07\">O despejo cai em fio fino, do centro pra borda, dividido em duas ou três levas.</li><li data-n=\"08\">A borra termina plana, sem cratera no meio e sem pó seco na parede do filtro.</li></ul>\n        </div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:6\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"t7\"><span class=\"num\">07</span><span class=\"titulo\">O cronômetro da coada</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"t7\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Marca da primeira gota à última, mira em 2min30 a 3min30 e corrige uma variável por coada.</p>\n          <p class=\"no-ebook\">Os critérios ficam no guia.</p>\n        </div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:7\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"t8\"><span class=\"num\">08</span><span class=\"titulo\">O coador enxaguado na hora</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"t8\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\">\n          <p>Enxágua o coador ainda morno e guarda o grão em pote opaco fechado, longe do fogão.</p>\n          <p class=\"no-ebook\">Os critérios ficam no guia.</p>\n        </div></div></div>\n      </li>\n\n    </ol>\n  </div>\n</section>\n\n<section class=\"bloco\" id=\"paginas\">\n  <div class=\"miolo\">\n    <h2 class=\"revela\">Oito páginas reais do miolo.</h2>\n    <p class=\"intro revela\" style=\"--i:1\">Do infográfico da premissa ao placar do caso, como saem no PDF e na versão web.</p>\n    <div class=\"galeria\"><figure class=\"pag revela\" style=\"--i:2\"><img src=\"/ebook-web/lp-pag-1.webp\" alt=\"Página real do guia: Infográfico\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>Infográfico</b>A premissa: o que separa a sua xícara da do balcão são oito variáveis, nunca a máquina</figcaption></figure><figure class=\"pag revela\" style=\"--i:3\"><img src=\"/ebook-web/lp-pag-2.webp\" alt=\"Página real do guia: O mapa\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>O mapa</b>As quatro famílias que decidem a coada: matéria, superfície, contato e constância</figcaption></figure><figure class=\"pag revela\" style=\"--i:4\"><img src=\"/ebook-web/lp-pag-3.webp\" alt=\"Página real do guia: O caso\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>O caso</b>O caso do guia, antes: duas xícaras por dia no balcão e a máquina de espresso no carrinho</figcaption></figure><figure class=\"pag revela\" style=\"--i:5\"><img src=\"/ebook-web/lp-pag-4.webp\" alt=\"Página real do guia: Abertura de variável\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>Abertura de variável</b>Cada variável abre em cena, com o defeito nomeado e a família da coada no topo</figcaption></figure><figure class=\"pag revela\" style=\"--i:6\"><img src=\"/ebook-web/lp-pag-5.webp\" alt=\"Página real do guia: Passo a passo\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>Passo a passo</b>O movimento em três passos: areia grossa, cronômetro e um clique por coada</figcaption></figure><figure class=\"pag revela\" style=\"--i:7\"><img src=\"/ebook-web/lp-pag-6.webp\" alt=\"Página real do guia: Calculadora\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>Calculadora</b>A ficha da coada: digita a economia de cada variável e a soma fecha sozinha</figcaption></figure><figure class=\"pag revela\" style=\"--i:8\"><img src=\"/ebook-web/lp-pag-7.webp\" alt=\"Página real do guia: Falas prontas\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>Falas prontas</b>O que a copa diz do café de casa, e o que você responde com a xícara na mão</figcaption></figure><figure class=\"pag revela\" style=\"--i:9\"><img src=\"/ebook-web/lp-pag-8.webp\" alt=\"Página real do guia: O placar\" width=\"450\" height=\"662\" loading=\"lazy\" decoding=\"async\"><figcaption><b>O placar</b>O caso do guia, depois: oito variáveis marcadas e o café da manhã trocado do balcão pro coador</figcaption></figure></div>\n  </div>\n</section>\n\n<section class=\"bloco\" id=\"leva\">\n  <div class=\"miolo\">\n    <h2 class=\"revela\">O que chega no seu email</h2>\n    <div class=\"leva\">\n      <figure class=\"capa revela\">\n        <img src=\"/ebook-web/capa-notas-do-cafe.webp\" alt=\"Capa do guia Café de Balcão no Coador de Casa\" width=\"280\" height=\"373\" loading=\"lazy\" decoding=\"async\">\n      </figure>\n      <div>\n        <ul class=\"kit\">\n          <li class=\"revela\"><b>O guia completo, web e PDF</b>Pra ler no navegador e pra guardar e imprimir.</li>\n          <li class=\"revela\" style=\"--i:1\"><b>O checklist da coada</b>Uma folha só, imprimível: risca uma variável por coada enquanto a água esquenta.</li>\n          <li class=\"revela\" style=\"--i:2\"><b>A ficha da coada</b>A economia de cada variável, com a faixa típica ao lado e o total do mês.</li>\n          <li class=\"revela\" style=\"--i:3\"><b>As falas prontas</b>As quatro frases que encerram o assunto na copa, com botão de copiar.</li>\n\n        </ul>\n        <p class=\"entrega revela\" style=\"--i:4\">Confirmou, o acesso abre na hora, no email do pedido.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"bloco\" id=\"votos\">\n  <div class=\"miolo\">\n<style>.votos.dois{max-width:720px}@media (min-width:720px){.votos.dois{grid-template-columns:repeat(2,1fr)}}</style>\n    <h2 class=\"revela\">Quem lê a news todo dia</h2>\n    <ul class=\"votos dois\">\n      <li class=\"voto revela\"><span class=\"inicial\" aria-hidden=\"true\">L</span><blockquote>“Estou aprendendo muito e as informações me tornam cada vez mais seguro para escolher um café de qualidade. Grato a todos.”</blockquote><p class=\"quem\">voto de leitor(a) na edição diária</p></li>\n      <li class=\"voto revela\" style=\"--i:1\"><span class=\"inicial\" aria-hidden=\"true\">L</span><blockquote>“Além de aprender sobre mais uma região que produz café de qualidade, também aprendi detalhes de um método de extração para tirar o melhor desse café. Sensacional!”</blockquote><p class=\"quem\">voto de leitor(a) na edição diária</p></li>\n    </ul>\n    <p class=\"nota revela\" style=\"--i:3\">Votos do formulário que fecha cada edição: a caixa é anônima por desenho, o leitor escreve sem assinar.</p>\n  </div>\n</section>\n\n<section class=\"bloco ficha centro\" id=\"ficha\">\n  <div class=\"miolo estreito\">\n    <h2 class=\"revela\">Três minutos lendo a xícara, e a próxima coada sai com o defeito apontado.</h2>\n    <p class=\"chamada revela\" style=\"--i:1\">Uma vez só. A próxima coada já passa pelas 8 variáveis. O guia em web e PDF, o checklist da coada, a ficha da coada e as falas prontas.</p>\n    <a class=\"botao revela\" style=\"--i:2\" href=\"/ebook-premium/checkout\">Quero o guia →</a>\n    <p class=\"micro revela\" style=\"--i:3\">uma vez só · pix ou cartão · acesso na hora</p>\n    <p class=\"garantia revela\" style=\"--i:4\"><b>Melhorou a coada ou devolve, em 7 dias.</b> Leu o guia e não encontrou nenhuma variável pra corrigir na sua coada? Responda o email do pedido em até 7 dias e devolvemos tudo.</p>\n    <p class=\"italico revela\" style=\"--i:5\">Custa menos que a máquina cara que espera o salário cair pra tirar o amargo.</p>\n  </div>\n</section>\n\n<section class=\"bloco\" id=\"perguntas\">\n  <div class=\"miolo\">\n    <h2 class=\"revela\">Perguntas de quem está na porta</h2>\n    <ol class=\"sanfona\">\n      <li class=\"dobra revela\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"p1\"><span class=\"num\">01</span><span class=\"titulo\">Pix, cartão ou boleto?</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"p1\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\"><p>Os três, uma vez só, R$ 27, pela Stripe. No pix e no cartão o acesso abre na hora; no boleto, quando o banco confirma.</p></div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:1\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"p2\"><span class=\"num\">02</span><span class=\"titulo\">Como recebo depois de confirmar?</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"p2\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\"><p>O acesso abre na hora: a versão web pra ler no navegador e o PDF pra guardar. O link também chega no email do pedido.</p></div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:2\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"p3\"><span class=\"num\">03</span><span class=\"titulo\">Quanto tempo leva?</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"p3\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\"><p>Três minutos lendo a xícara antes de mexer em qualquer variável, e uma coada por variável depois. O guia inteiro se lê numa semana de manhãs, uma variável por capítulo, e a primeira diferença na boca costuma aparecer já na segunda coada.</p></div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:3\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"p4\"><span class=\"num\">04</span><span class=\"titulo\">8 variáveis e 3 minutos: as contas batem?</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"p4\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\"><p>Batem. Os 3 minutos são o diagnóstico da xícara: um pra provar, um pro rótulo, um pro relógio. Ele aponta por qual das 8 variáveis começar, e daí é uma variável por coada, na ordem em que a água encontra o café.</p></div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:4\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"p5\"><span class=\"num\">05</span><span class=\"titulo\">Preciso de equipamento novo?</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"p5\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\"><p>Nenhuma máquina. O guia usa o coador de papel que já está no armário, o relógio do celular e uma balança de cozinha pra pesar a dose. Sem moedor em casa, peça na torrefação pra moer na hora, na textura pra coador.</p></div></div></div>\n      </li>\n      <li class=\"dobra revela\" style=\"--i:5\">\n        <button class=\"cabeca\" type=\"button\" aria-expanded=\"false\" aria-controls=\"p6\"><span class=\"num\">06</span><span class=\"titulo\">E se não funcionar pra mim?</span><span class=\"mais\" aria-hidden=\"true\"></span></button>\n        <div class=\"corpo\" id=\"p6\" hidden><div class=\"corpo-miolo\"><div class=\"corpo-texto\"><p>Funciona pra quem coa com coador de papel e ainda paga o café do balcão: grão de mercado ou de torrefação, chaleira comum, qualquer fogão. Se você leu o guia e não achou nenhuma variável pra corrigir na sua coada, responda o email do pedido em até 7 dias e devolvemos o valor inteiro.</p></div></div></div>\n      </li>\n\n    </ol>\n  </div>\n</section>\n</main>\n\n<footer class=\"rodape\">\n  <a class=\"marca-news\" href=\"#inicio\"><span class=\"palavra\"><em>Notas</em> do Café</span></a>\n  <p>Bom café. Até sábado.</p>\n  <p>Stripe · pix, cartão ou boleto</p>\n</footer>";
export const JS = "(function(){\n  'use strict';\n  var reduzido = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  var PARES = [\n    {aba:\"lista\", teste:1, ctx:\"lista do mercado\", antes:\"pão · leite · manteiga · <span class=\\\"lapis\\\">café 500 g extraforte, já moído</span> (o de sempre) · filtro de papel\", depois:\"pão · leite · manteiga · café em grão 250 g, torra média, com data de torra no pacote · filtro de papel\", falhou:\"variável 1 · o grão e a torra\", entrou:\"O extraforte moído chega sem aroma dias depois de aberto e com o açúcar do grão queimado. Grão inteiro de torra média, em pacote que acaba no mês, entrega aroma até a última xícara.\", rotulo:\"Critério\", criterio:\"O pacote é de grão inteiro, torra média, e traz a data de torra impressa, não só a validade.\"},\n    {aba:\"torrefação\", teste:2, ctx:\"pedido na torrefação\", antes:\"Oi, me separa 250 g daquele do Cerrado? <span class=\\\"lapis\\\">Pode moer bem fininho, que rende mais</span>.\", depois:\"Oi, me separa 250 g daquele do Cerrado? Moagem pra coador de papel, grossa como areia de praia.\", falhou:\"variável 2 · a moagem\", entrou:\"Pó fino é calibrado pra espresso: no coador ele segura a água mais de cinco minutos e passa do doce pro amargo. Em areia grossa, a água atravessa em perto de três.\", rotulo:\"Critério\", criterio:\"O pó tem textura de areia grossa entre os dedos e a coada escoa entre 2min30 e 3min30.\"},\n    {aba:\"receita\", teste:3, ctx:\"receita salva no celular\", antes:\"Café da manhã: <span class=\\\"lapis\\\">3 colheres de sopa bem cheias</span> pra jarra de meio litro. Saiu fraco, põe mais uma.\", depois:\"Café da manhã: 31 g na balança pra 500 ml de água, 1 para 16. Saiu fraco, sobe um grama amanhã e prova.\", falhou:\"variável 3 · a proporção\", entrou:\"A colher de sopa muda de peso com a moagem, a umidade do pó e a mão de quem serve, e a xícara muda junto. Pesada uma vez, a dose repete todo dia.\", rotulo:\"O que mudou\", criterio:\"A colher de sopa muda de peso com a moagem, a umidade do pó e a mão de quem serve, e a xícara muda junto. Pesada uma vez, a dose repete todo dia.\"},\n    {aba:\"chaleira\", teste:4, ctx:\"recado no grupo da casa\", antes:\"Quem acordar primeiro: <span class=\\\"lapis\\\">chaleira apitou, joga a água direto no café</span>, senão esfria.\", depois:\"Quem acordar primeiro: chaleira apitou, desliga o fogo, tira a tampa e conta 40 segundos antes de molhar o pó.\", falhou:\"variável 4 · a água e a temperatura\", entrou:\"Água a cem graus arranca o amargo antes da hora, e o gosto de queimado ia na conta do grão. Quarenta segundos de tampa aberta põem a água na faixa de 92 a 96 graus.\", rotulo:\"Critério\", criterio:\"A água espera de 30 a 60 segundos fora da fervura, com a tampa aberta, antes de encostar no pó.\"},\n    {aba:\"despejo\", teste:6, ctx:\"dica no grupo da família\", antes:\"Meu jeito: <span class=\\\"lapis\\\">vira a chaleira toda de uma vez no meio do filtro</span>, que coa mais rápido e não esfria.\", depois:\"Meu jeito: molha o pó, espera o gás baixar e despeja em fio fino, do centro pra borda, em duas levas.\", falhou:\"variável 6 · a técnica de despejo\", entrou:\"O jato único abria um canal no meio e metade do pó ficava seco na parede do filtro. Em espiral, a água toca o café inteiro e a mesma dose sai mais doce.\", rotulo:\"Critério\", criterio:\"O despejo cai em fio fino, em espiral do centro pra borda, e a borra termina plana, sem cratera.\"},\n    {aba:\"caderno\", teste:7, ctx:\"anotação da coada de sábado\", antes:\"Sábado: saiu amargo de novo. <span class=\\\"lapis\\\">Troquei o pó, a água e a dose de uma vez</span>, amanhã vejo no que deu.\", depois:\"Sábado: escoou em 5min10, amargo. Amanhã abro um clique na moagem, mantenho o resto e cronometro de novo.\", falhou:\"variável 7 · o tempo total\", entrou:\"Três mudanças na mesma coada apagam a prova de qual funcionou. O cronômetro aponta a variável, e uma mudança por coada mostra o que resolveu.\", rotulo:\"O que mudou\", criterio:\"Três mudanças na mesma coada apagam a prova de qual funcionou. O cronômetro aponta a variável, e uma mudança por coada mostra o que resolveu.\"}\n  ];\n\n  var cartao = document.getElementById('cartao');\n  var faceAntes = document.getElementById('faceAntes');\n  var faceDepois = document.getElementById('faceDepois');\n  var trechoAntes = document.getElementById('trechoAntes');\n  var trechoDepois = document.getElementById('trechoDepois');\n  var ondeFalhou = document.getElementById('ondeFalhou');\n  var oQueEntrou = document.getElementById('oQueEntrou');\n  var criterio = document.getElementById('criterio');\n  var criterioTexto = document.getElementById('criterioTexto');\n  var estados = cartao.querySelectorAll('.estado-texto');\n  var abas = Array.prototype.slice.call(document.querySelectorAll('.par'));\n  var risco = document.querySelector('.risco');\n  var interruptor = document.getElementById('interruptor');\n  var lados = Array.prototype.slice.call(interruptor.querySelectorAll('.lado'));\n\n  var atual = 0;\n  var lado = 'antes';\n  var tocou = false;\n  var naTela = true;\n\n  function raf2(fn){ requestAnimationFrame(function(){ requestAnimationFrame(fn); }); }\n\n  function escreve(i){\n    var p = PARES[i];\n    trechoAntes.innerHTML = p.antes;\n    trechoDepois.textContent = p.depois;\n    trechoAntes.classList.toggle('como-titulo', !!p.titulo);\n    trechoDepois.classList.toggle('como-titulo', !!p.titulo);\n    ondeFalhou.textContent = p.falhou;\n    oQueEntrou.textContent = p.entrou;\n    criterioTexto.textContent = p.criterio;\n    document.getElementById('criterioRotulo').textContent = p.rotulo;\n    document.getElementById('ctxAntes').textContent = p.ctx;\n    document.getElementById('ctxDepois').textContent = p.ctx;\n    estados[0].textContent = 'variável ' + p.teste + ' · falhou';\n    estados[1].textContent = 'variável ' + p.teste + ' · passou';\n    cartao.setAttribute('aria-label', 'Cartão com ' + p.ctx + '. Toque pra virar entre antes e depois.');\n  }\n\n  /* o cartão tem UMA altura, a maior dos dez trechos: virar e trocar de trecho não mexe na página */\n  function mede(){\n    var guardado = atual, alto = 0, pe = 0;\n    cartao.classList.add('medindo');\n    criterio.style.minHeight = '0px';\n    for (var i = 0; i < PARES.length; i++){\n      escreve(i);\n      alto = Math.max(alto, faceAntes.offsetHeight, faceDepois.offsetHeight);\n      pe = Math.max(pe, criterio.offsetHeight);\n    }\n    escreve(guardado);\n    cartao.classList.remove('medindo');\n    cartao.style.height = alto + 'px';\n    criterio.style.minHeight = pe + 'px';\n  }\n\n  /* FLIP: onde estava, muda o layout, onde ficou, inverte com transform e solta no quadro seguinte */\n  function flip(el, muda){\n    var antes = el.getBoundingClientRect();\n    el.style.transition = 'none';\n    el.style.transform = '';\n    muda();\n    var depois = el.getBoundingClientRect();\n    if (reduzido || !antes.width || !depois.width){ void el.offsetWidth; el.style.transition = ''; return; }\n    var dx = antes.left - depois.left, sx = antes.width / depois.width;\n    el.style.transform = 'translateX(' + dx.toFixed(1) + 'px) scaleX(' + sx.toFixed(4) + ')';\n    void el.offsetWidth;\n    el.style.transition = '';\n    requestAnimationFrame(function(){ el.style.transform = ''; });\n  }\n\n  function poeRisco(animar){\n    var aba = abas[atual];\n    var muda = function(){\n      risco.style.left = aba.offsetLeft + 'px';\n      risco.style.top = (aba.offsetTop + aba.offsetHeight - 2) + 'px';\n      risco.style.width = aba.offsetWidth + 'px';\n    };\n    if (animar) flip(risco, muda);\n    else { risco.style.transition = 'none'; muda(); void risco.offsetWidth; risco.style.transition = ''; }\n  }\n\n  function vira(novo){\n    if (novo === lado) return;\n    lado = novo;\n    var deDepois = lado === 'depois';\n    cartao.classList.toggle('depois', deDepois);\n    cartao.setAttribute('aria-pressed', deDepois ? 'true' : 'false');\n    interruptor.classList.toggle('em-depois', deDepois);\n    lados.forEach(function(b){ b.setAttribute('aria-pressed', b.dataset.lado === lado ? 'true' : 'false'); });\n  }\n\n  function trocaPar(i){\n    if (i === atual) return;\n    atual = i;\n    abas.forEach(function(a, k){ a.setAttribute('aria-selected', k === i ? 'true' : 'false'); });\n    poeRisco(true);\n    if (reduzido){ escreve(i); return; }\n    trechoAntes.classList.add('trocando');\n    trechoDepois.classList.add('trocando');\n    criterio.classList.add('trocando');\n    cartao.classList.remove('pousou');\n    setTimeout(function(){\n      escreve(i);\n      raf2(function(){\n        trechoAntes.classList.remove('trocando');\n        trechoDepois.classList.remove('trocando');\n        criterio.classList.remove('trocando');\n        if (naTela) cartao.classList.add('pousou');\n      });\n    }, 200);\n  }\n\n  /* o cartão vira sozinho até o primeiro toque; para com a aba escondida ou fora da tela */\n  var relogio = null;\n  function agenda(){\n    clearTimeout(relogio);\n    if (reduzido || tocou || document.hidden || !naTela) return;\n    relogio = setTimeout(function(){\n      if (tocou || document.hidden || !naTela) return;\n      vira(lado === 'antes' ? 'depois' : 'antes');\n      agenda();\n    }, 5000);\n  }\n  function toque(){ if (!tocou){ tocou = true; clearTimeout(relogio); } }\n\n  abas.forEach(function(a, i){\n    a.addEventListener('click', function(){ toque(); trocaPar(i); });\n    a.addEventListener('keydown', function(e){\n      var passo = e.key === 'ArrowRight' ? 1 : (e.key === 'ArrowLeft' ? -1 : 0);\n      if (!passo) return;\n      e.preventDefault(); toque();\n      var n = (i + passo + abas.length) % abas.length;\n      abas[n].focus(); trocaPar(n);\n    });\n  });\n  lados.forEach(function(b){ b.addEventListener('click', function(){ toque(); vira(b.dataset.lado); }); });\n  cartao.addEventListener('click', function(){ toque(); vira(lado === 'antes' ? 'depois' : 'antes'); });\n  cartao.addEventListener('keydown', function(e){\n    if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); toque(); vira(lado === 'antes' ? 'depois' : 'antes'); }\n  });\n\n  var olhoCartao = new IntersectionObserver(function(itens){\n    itens.forEach(function(item){\n      naTela = item.isIntersecting;\n      if (naTela){\n        raf2(function(){ cartao.classList.remove('longe'); cartao.classList.add('pousou'); });\n        agenda();\n      } else {\n        cartao.classList.add('longe');\n        cartao.classList.remove('pousou');\n        clearTimeout(relogio);\n      }\n    });\n  }, {threshold: 0.2});\n\n  document.addEventListener('visibilitychange', function(){\n    if (document.hidden) clearTimeout(relogio); else agenda();\n  });\n\n  /* inclinação leve no ponteiro, só onde existe ponteiro fino */\n  if (!reduzido && window.matchMedia('(hover:hover) and (pointer:fine)').matches){\n    var palco = document.querySelector('.palco');\n    var ax = 0, ay = 0, cx = 0, cy = 0, quadro = null;\n    var anda = function(){\n      cx += (ax - cx) * 0.12; cy += (ay - cy) * 0.12;\n      palco.style.transform = 'rotateX(' + cy.toFixed(2) + 'deg) rotateY(' + cx.toFixed(2) + 'deg)';\n      quadro = (Math.abs(ax - cx) > 0.02 || Math.abs(ay - cy) > 0.02) ? requestAnimationFrame(anda) : null;\n    };\n    var puxa = function(){ if (quadro === null && !document.hidden) quadro = requestAnimationFrame(anda); };\n    palco.style.transformStyle = 'preserve-3d';\n    palco.addEventListener('pointermove', function(e){\n      var r = palco.getBoundingClientRect();\n      ax = ((e.clientX - r.left) / r.width - 0.5) * 5;\n      ay = -((e.clientY - r.top) / r.height - 0.5) * 4;\n      puxa();\n    });\n    palco.addEventListener('pointerleave', function(){ ax = 0; ay = 0; puxa(); });\n    document.addEventListener('visibilitychange', function(){\n      if (document.hidden && quadro !== null){ cancelAnimationFrame(quadro); quadro = null; } else puxa();\n    });\n  }\n\n  /* sanfonas */\n  Array.prototype.forEach.call(document.querySelectorAll('.cabeca'), function(cabeca){\n    var corpo = document.getElementById(cabeca.getAttribute('aria-controls'));\n    cabeca.addEventListener('click', function(){\n      var aberto = cabeca.getAttribute('aria-expanded') === 'true';\n      cabeca.setAttribute('aria-expanded', aberto ? 'false' : 'true');\n      if (aberto){\n        corpo.classList.remove('aberto');\n        if (reduzido){ corpo.hidden = true; return; }\n        var fecha = function(e){\n          if (e && e.target !== corpo) return;\n          corpo.removeEventListener('transitionend', fecha);\n          if (!corpo.classList.contains('aberto')) corpo.hidden = true;\n        };\n        corpo.addEventListener('transitionend', fecha);\n        setTimeout(fecha, 600);\n      } else {\n        corpo.hidden = false;\n        void corpo.offsetHeight;\n        corpo.classList.add('aberto');\n      }\n    });\n  });\n\n  /* reveals: entram ao aparecer e se rearmam ao sair */\n  var olhoRevela = new IntersectionObserver(function(itens){\n    itens.forEach(function(item){ item.target.classList.toggle('dentro', item.isIntersecting); });\n  }, {threshold: 0.1, rootMargin: '0px 0px -5% 0px'});\n  Array.prototype.forEach.call(document.querySelectorAll('.revela'), function(el){ olhoRevela.observe(el); });\n\n  /* primeiro quadro desenhado antes de qualquer animação */\n  escreve(atual);\n  mede();\n  poeRisco(false);\n  if (reduzido) cartao.classList.add('pousou');\n  var remede = function(){ mede(); poeRisco(false); };\n  if (document.fonts && document.fonts.ready) document.fonts.ready.then(remede);\n  if ('ResizeObserver' in window){\n    var larguraAnterior = cartao.offsetWidth;\n    new ResizeObserver(function(){\n      if (Math.abs(cartao.offsetWidth - larguraAnterior) < 1) return;\n      larguraAnterior = cartao.offsetWidth;\n      remede();\n    }).observe(document.querySelector('.palco'));\n  } else {\n    window.addEventListener('resize', remede);\n  }\n  olhoCartao.observe(cartao);\n})();";
